package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"sort"
	"strconv"
	"strings"
)

// notice heads every generated file and names the input it came from.
const notice = "// Generated by 'make generate-client-sdk' from %s.\n// Do not edit: change the source and regenerate.\n"

const (
	documentSource = "internal/transport/http/httpapi/openapi.json"
	requestIndent  = "      "
)

// operationsTarget is what differs between the operations file of the core
// package and that of a module package.
type operationsTarget struct {
	notice      string
	runtimeFrom string
	typesFrom   string
	description string
}

var coreTarget = operationsTarget{
	notice:      fmt.Sprintf(notice, documentSource),
	runtimeFrom: "../operation.js",
	typesFrom:   "./core-api.js",
	description: "The core's HTTP API, one method per operation, bound to one transport.",
}

func renderOperations(ops []operation) []byte {
	return renderOperationsFor(ops, coreTarget)
}

func renderOperationsFor(ops []operation, target operationsTarget) []byte {
	var b bytes.Buffer

	b.WriteString(target.notice)
	b.WriteString("\n")
	fmt.Fprintf(&b, "import type { Operation, Transport } from %s;\n", tsString(target.runtimeFrom))
	fmt.Fprintf(&b, "import type { operations } from %s;\n\n", tsString(target.typesFrom))

	b.WriteString("/** Every operation the document declares, keyed by its operationId. */\n")
	b.WriteString("export const operationTable = {\n")

	for _, op := range ops {
		b.WriteString("  " + tsString(op.ID) + ": " + descriptor(op) + ",\n")
	}

	b.WriteString("} as const satisfies Record<string, Operation>;\n\n")

	b.WriteString("/** " + target.description + " */\n")
	b.WriteString("export interface Operations {\n")

	for i, op := range ops {
		if i > 0 {
			b.WriteString("\n")
		}

		b.WriteString(signature(op))
	}

	b.WriteString("}\n\n")

	b.WriteString("/** bindOperations closes every operation over the transport that sends it. */\n")
	b.WriteString("export function bindOperations(transport: Transport): Operations {\n")
	b.WriteString("  return {\n")

	for _, op := range ops {
		request := "request"
		if op.RequestOptional() {
			request = "request = {}"
		}

		fmt.Fprintf(&b, "    %s: (%s, signal) => transport.call(operationTable[%s], request, signal),\n",
			op.Name, request, tsString(op.ID))
	}

	b.WriteString("  };\n")
	b.WriteString("}\n")

	return b.Bytes()
}

func descriptor(op operation) string {
	fields := []string{
		"id: " + tsString(op.ID),
		"method: " + tsString(op.Method),
		"path: " + tsString(op.Path),
	}

	if op.Body != "" {
		fields = append(fields, "body: "+tsString(op.Body))
	}

	fields = append(fields,
		"response: "+tsString(string(op.Response)),
		"anonymous: "+strconv.FormatBool(op.Anonymous))

	if op.LongRunning {
		fields = append(fields, "longRunning: true")
	}

	return "{ " + strings.Join(fields, ", ") + " }"
}

// signature is one method of the Operations interface. Its types index into
// the openapi-typescript output, so no schema is repeated here.
func signature(op operation) string {
	var b strings.Builder

	b.WriteString("  /**\n")
	fmt.Fprintf(&b, "   * %s %s\n", op.Method, op.Path)

	if op.Summary != "" {
		b.WriteString("   *\n")
		fmt.Fprintf(&b, "   * %s\n", strings.ReplaceAll(op.Summary, "*/", "*\\/"))
	}

	if op.Anonymous {
		b.WriteString("   *\n   * Takes no credential.\n")
	}

	b.WriteString("   */\n")

	optional := ""
	if op.RequestOptional() {
		optional = "?"
	}

	members := requestMembers(op)

	if len(members) == 0 {
		fmt.Fprintf(&b, "  %s(\n    request?: Record<string, never>,\n", op.Name)
	} else {
		fmt.Fprintf(&b, "  %s(\n    request%s: {\n", op.Name, optional)

		for _, member := range members {
			b.WriteString(requestIndent + member + ";\n")
		}

		b.WriteString("    },\n")
	}

	fmt.Fprintf(&b, "    signal?: AbortSignal,\n  ): Promise<%s>;\n", responseType(op))

	return b.String()
}

func requestMembers(op operation) []string {
	index := "operations[" + tsString(op.ID) + "]"

	var members []string

	if len(op.PathParams) > 0 {
		members = append(members, "path: "+index+"[\"parameters\"][\"path\"]")
	}

	if len(op.Query) > 0 {
		members = append(members, optionalMember("query", anyRequired(op.Query))+index+"[\"parameters\"][\"query\"]")
	}

	if len(op.Header) > 0 {
		members = append(members, optionalMember("header", anyRequired(op.Header))+index+"[\"parameters\"][\"header\"]")
	}

	if op.Body != "" {
		// Not BodyInit: that is a DOM lib name @types/node does not declare, and
		// a Node consumer without the DOM lib could not type-check the package.
		body := "RequestInit[\"body\"]"
		if op.Body == mediaJSON {
			body = "NonNullable<" + index + "[\"requestBody\"]>[\"content\"][" + tsString(mediaJSON) + "]"
		}

		members = append(members, optionalMember("body", op.BodyRequired)+body)

		// A binary body is a file upload. With onProgress set, the transport
		// sends over XMLHttpRequest, the only browser API that reports progress.
		if op.Body == mediaBinary {
			members = append(members, "onProgress?: (sent: number, total: number) => void")
		}
	}

	return members
}

func optionalMember(name string, required bool) string {
	if required {
		return name + ": "
	}

	return name + "?: "
}

func responseType(op operation) string {
	switch op.Response {
	case responseJSON:
		parts := make([]string, 0, len(op.JSONStatuses))
		for _, status := range op.JSONStatuses {
			parts = append(parts, fmt.Sprintf("operations[%s][\"responses\"][%s][\"content\"][%s]",
				tsString(op.ID), status, tsString(mediaJSON)))
		}

		return strings.Join(parts, " | ")
	case responseText:
		return "string"
	case responseRaw:
		return "Response"
	case responseNone:
		return "void"
	}

	return "unknown"
}

func renderErrors(codes []errorCode) []byte {
	var b bytes.Buffer

	fmt.Fprintf(&b, notice, "docs/errors/error-codes.json")
	b.WriteString("\n")
	b.WriteString("/**\n * A code the core returns in a problem document. A module returns codes from\n")
	b.WriteString(" * its own domain, so a refusal may carry a code this union does not name.\n */\n")
	b.WriteString("export type ErrorCode =\n")

	for _, code := range codes {
		b.WriteString("  | " + tsString(code.Code) + "\n")
	}

	b.Truncate(b.Len() - 1)
	b.WriteString(";\n\n")

	b.WriteString("/** What the error reference says about one code. */\n")
	b.WriteString("export interface ErrorCodeEntry {\n")
	b.WriteString("  readonly status: number;\n")
	b.WriteString("  readonly retryable: boolean;\n")
	b.WriteString("  /** The names the code's params carry, in the order the reference lists them. */\n")
	b.WriteString("  readonly params: readonly string[];\n")
	b.WriteString("  readonly summary: string;\n")
	b.WriteString("  /** What a caller does about it. */\n")
	b.WriteString("  readonly action: string;\n")
	b.WriteString("}\n\n")

	b.WriteString("/** Every core code, keyed by code. */\n")
	b.WriteString("export const errorCodes: Readonly<Record<ErrorCode, ErrorCodeEntry>> = {\n")

	for _, code := range codes {
		fmt.Fprintf(&b, "  %s: { status: %d, retryable: %t, params: %s, summary: %s, action: %s },\n",
			tsString(code.Code), code.Status, code.Retryable, tsStrings(code.Params),
			tsString(code.Summary), tsString(code.Action))
	}

	b.WriteString("};\n")

	return b.Bytes()
}

// renderEvents writes events.ts. Every payload is typed unknown because the
// core publishes no payload schema.
func renderEvents(file eventTypesFile) []byte {
	var b bytes.Buffer

	fmt.Fprintf(&b, notice, "docs/vocabularies/event-types.json")
	b.WriteString("\n")
	fmt.Fprintf(&b, "/** The event-type vocabulary version these names come from. */\n"+
		"export const eventTypesVersion = %s;\n\n", tsString(file.Version))

	b.WriteString("/** An event type this build publishes on GET /api/v1/events. */\n")
	b.WriteString("export type EventType =\n")

	for _, entry := range file.Entries {
		b.WriteString("  | " + tsString(entry.Type) + "\n")
	}

	b.Truncate(b.Len() - 1)
	b.WriteString(";\n\n")

	classes := distinct(file.Entries, func(e eventType) string { return e.Class })

	b.WriteString("/** The class of an event type: what a reader that missed one has lost. */\n")
	b.WriteString("export type EventClass = " + unionOf(classes) + ";\n\n")

	b.WriteString("/** Every event type, in the order the vocabulary lists them. */\n")
	b.WriteString("export const eventTypes: readonly EventType[] = [\n")

	for _, entry := range file.Entries {
		b.WriteString("  " + tsString(entry.Type) + ",\n")
	}

	b.WriteString("];\n\n")

	b.WriteString("/** The class of each event type. */\n")
	b.WriteString("export const eventClasses: Readonly<Record<EventType, EventClass>> = {\n")

	for _, entry := range file.Entries {
		fmt.Fprintf(&b, "  %s: %s,\n", tsString(entry.Type), tsString(entry.Class))
	}

	b.WriteString("};\n\n")

	b.WriteString("/**\n")
	b.WriteString(" * The payload of each event type. Every entry is `unknown`: the core publishes\n")
	b.WriteString(" * no payload schema, so a reader narrows `data` itself. When the document\n")
	b.WriteString(" * carries one per type, the type is declared here.\n")
	b.WriteString(" */\n")
	b.WriteString("export type EventPayloads = { readonly [T in EventType]: unknown };\n")

	return b.Bytes()
}

func renderVocabulary(file authzFile) []byte {
	var b bytes.Buffer

	fmt.Fprintf(&b, notice, "docs/vocabularies/authorization.json")
	b.WriteString("\n")
	fmt.Fprintf(&b, "/** The authorization vocabulary version these names come from. */\n"+
		"export const authorizationVersion = %s;\n\n", tsString(file.Version))

	actions := names(file.Actions, func(a authzAction) string { return a.Action })
	types := names(file.Types, func(t authzType) string { return t.Type })
	relations := names(file.Relations, func(r authzRelation) string { return r.Relation })

	b.WriteString("/** An action a grant confers, such as `observe` on a device. */\n")
	b.WriteString("export type AuthorizationAction = " + unionOf(actions) + ";\n\n")
	b.WriteString("/** A type a grant names as its object or its subject. */\n")
	b.WriteString("export type AuthorizationType = " + unionOf(types) + ";\n\n")
	b.WriteString("/** A relation between a subject and an object. */\n")
	b.WriteString("export type AuthorizationRelation = " + unionOf(relations) + ";\n\n")

	b.WriteString("/** Every action, in the order the vocabulary lists them. */\n")
	b.WriteString("export const authorizationActions: readonly AuthorizationAction[] = " + tsStrings(actions) + ";\n\n")
	b.WriteString("/** Every type, in the order the vocabulary lists them. */\n")
	b.WriteString("export const authorizationTypes: readonly AuthorizationType[] = " + tsStrings(types) + ";\n\n")
	b.WriteString("/** Every relation, in the order the vocabulary lists them. */\n")
	b.WriteString("export const authorizationRelations: readonly AuthorizationRelation[] = " +
		tsStrings(relations) + ";\n\n")

	b.WriteString("/** The types a grant may name as its subject. */\n")
	b.WriteString("export const subjectTypes: readonly AuthorizationType[] = " +
		tsStrings(typesWhere(file.Types, func(t authzType) bool { return t.Subject })) + ";\n\n")

	b.WriteString("/** The types a grant may name as its object. */\n")
	b.WriteString("export const objectTypes: readonly AuthorizationType[] = " +
		tsStrings(typesWhere(file.Types, func(t authzType) bool { return t.Object })) + ";\n")

	return b.Bytes()
}

func typesWhere(types []authzType, keep func(authzType) bool) []string {
	var out []string

	for _, t := range types {
		if keep(t) {
			out = append(out, t.Type)
		}
	}

	return out
}

// stampVersion rewrites the version field of package.json and leaves the rest
// of the file as it is.
func stampVersion(manifest []byte, version string) ([]byte, error) {
	const field = `"version": "`

	start := bytes.Index(manifest, []byte(field))
	if start < 0 {
		return nil, errNoVersionField
	}

	start += len(field)

	end := bytes.IndexByte(manifest[start:], '"')
	if end < 0 {
		return nil, errNoVersionField
	}

	out := make([]byte, 0, len(manifest)+len(version))
	out = append(out, manifest[:start]...)
	out = append(out, version...)
	out = append(out, manifest[start+end:]...)

	return out, nil
}

func unionOf(values []string) string {
	return strings.Join(quoted(values), " | ")
}

func quoted(values []string) []string {
	out := make([]string, 0, len(values))
	for _, v := range values {
		out = append(out, tsString(v))
	}

	return out
}

func names[T any](entries []T, name func(T) string) []string {
	out := make([]string, 0, len(entries))
	for _, entry := range entries {
		out = append(out, name(entry))
	}

	return out
}

func distinct[T any](entries []T, key func(T) string) []string {
	seen := map[string]struct{}{}

	var out []string

	for _, entry := range entries {
		k := key(entry)
		if _, ok := seen[k]; ok {
			continue
		}

		seen[k] = struct{}{}
		out = append(out, k)
	}

	sort.Strings(out)

	return out
}

// tsString returns a TypeScript string literal. JSON escaping is valid
// JavaScript. HTML escaping is off so `<` stays `<`.
func tsString(s string) string {
	var b bytes.Buffer

	enc := json.NewEncoder(&b)
	enc.SetEscapeHTML(false)

	// A string cannot fail to encode.
	_ = enc.Encode(s)

	return strings.TrimSuffix(b.String(), "\n")
}

func tsStrings(values []string) string {
	return "[" + strings.Join(quoted(values), ", ") + "]"
}
